from pathlib import Path
import base64
root=Path("ios")
p=root/"IGNIDOWake/StreakParity.swift"
s=p.read_text()
if 'import SceneKit' not in s:
    s=s.replace('import SwiftUI','import SwiftUI\nimport SceneKit\nimport UIKit',1)
start=s.find('struct GrowthCompanionView: View {')
end=s.find('private struct DragonFarWingShape: Shape {', start)
if start < 0 or end < 0: raise SystemExit("iOS GrowthCompanionView replacement markers missing")
replacement=base64.b64decode("""""").decode()
s=s[:start]+replacement+"\n\n"+s[end:]
p.write_text(s)
p=root/"IGNIDOWake/Info.plist"
s=p.read_text().replace('<string>2.6.0</string>','<string>2.7.0</string>',1).replace('<string>160</string>','<string>170</string>',1)
p.write_text(s)
p=root/"project.yml"
s=p.read_text().replace('CFBundleShortVersionString: "2.6.0"','CFBundleShortVersionString: "2.7.0"',1).replace('CFBundleVersion: "160"','CFBundleVersion: "170"',1)
p.write_text(s)
assert 'SCNView' in (root/"IGNIDOWake/StreakParity.swift").read_text()
assert 'dragon_realistic' in (root/"IGNIDOWake/StreakParity.swift").read_text()
print("iOS 2.7.0 3D scene patch applied")
